// Custom, dependency-free i18n dictionaries for the Care Team portal.
// English is the source of truth (its keys define `TranslationKey`); the other
// languages are full dictionaries and any accidental gap falls back to English
// at runtime. UI text only — never backend-provided dynamic data.

export const LANGS = ["en", "ar", "fr", "es", "de"] as const;
export type Lang = (typeof LANGS)[number];

export const LANG_NAMES: Record<Lang, string> = {
  en: "English",
  ar: "العربية",
  fr: "Français",
  es: "Español",
  de: "Deutsch",
};

export const RTL_LANGS: ReadonlySet<Lang> = new Set<Lang>(["ar"]);

