  "ai.family.response.medical": "يمكنني مساعدتك في إعداد الأسئلة، لكن لا يمكنني تشخيص الأعراض أو التوصية بعلاج. تواصل مع فريق الرعاية للحصول على إرشاد طبي. إذا كانت الحالة طارئة، فاتصل بخدمات الطوارئ المحلية فورًا.", "ai.family.response.memories": "جرّب استعادة صورة مألوفة أو مقطع فيديو قصير أو تسجيل صوتي. اختر ذكرى هادئة واحدة، وشارك ما تتذكره عنها، وادعُ من تحب للرد دون ضغط.", "ai.family.response.encouragement": "يمكنك أن تكتب: «أنا فخور بالجهد الذي تبذله. خذها خطوة بخطوة، وأنا معك». اجعل الرسالة دافئة ومحددة ومن دون ضغط.", "ai.family.response.appointments": "افتح المواعيد لمراجعة الزيارات القادمة والتفاصيل المتاحة. لتغيير الموعد أو لطرح أسئلة طبية، تواصل مع فريق الرعاية مباشرة.", "ai.family.response.messages": "استخدم الرسائل للتواصل غير العاجل مع فريق الرعاية. اجعل الرسالة واضحة وأدرج السؤال الذي تريد منهم الإجابة عنه.", "ai.family.response.reports": "تلخّص التقارير أداء الأنشطة المسجل، مثل الإكمال والتوقيت. وهي لا تشخّص أي حالة. يمكن لفريق الرعاية شرح معنى النتائج ضمن سياقها.", "ai.family.response.activities": "يوضح أداء الأنشطة ما تم تسجيله أثناء تمارين NeuroBridge، مثل الإكمال أو أنماط الاستجابة. وهو ليس تشخيصًا أو توصية علاجية.", "ai.family.response.care": "يمكنني مساعدتك في إعداد أسئلة مثل:\n• ما الذي تغير في أداء الأنشطة المسجل؟\n• على ماذا نركز قبل الزيارة القادمة؟\n• ما الأنشطة التي ينبغي أن نراجعها معًا؟", "ai.family.response.settings": "افتح الإعدادات من الشريط الجانبي لمراجعة خيارات اللغة والحساب وإمكانية الوصول. أخبرني أي إعداد تريد العثور عليه.", "ai.family.response.usage": "استخدم الشريط الجانبي لفتح الذكريات أو الأنشطة أو التقارير أو المواعيد أو الرسائل. أخبرني بما تريد فعله وسأرشدك إلى المكان المناسب.", "ai.family.response.unknown": "لست متأكدًا مما تقصده بعد. يمكنني المساعدة في أنشطة NeuroBridge أو الذكريات أو التقارير أو المواعيد أو الرسائل الداعمة أو أسئلة فريق الرعاية.",
