  "ai.family.response.medical":"Ich kann beim Vorbereiten von Fragen helfen, aber keine Symptome diagnostizieren oder Behandlungen empfehlen. Wenden Sie sich für medizinische Beratung an das Betreuungsteam. Bei einem möglichen Notfall rufen Sie sofort den örtlichen Notdienst.","ai.family.response.memories":"Sehen Sie gemeinsam ein vertrautes Foto, ein kurzes Video oder eine Sprachaufnahme an. Wählen Sie eine ruhige Erinnerung und laden Sie Ihren Angehörigen ohne Druck zum Antworten ein.","ai.family.response.encouragement":"Sie könnten schreiben: „Ich bin stolz auf deine Mühe. Geh Schritt für Schritt – ich bin bei dir.“ Bleiben Sie herzlich, konkret und ohne Druck.","ai.family.response.appointments":"Öffnen Sie Termine, um bevorstehende Besuche zu sehen. Wenden Sie sich bei Änderungen oder medizinischen Fragen direkt an das Betreuungsteam.","ai.family.response.messages":"Nutzen Sie Nachrichten für nicht dringende Mitteilungen an das Betreuungsteam. Formulieren Sie klar und nennen Sie die Frage, die beantwortet werden soll.","ai.family.response.reports":"Berichte fassen aufgezeichnete Leistungen wie Abschluss und Zeit zusammen. Sie sind keine Diagnose. Das Betreuungsteam kann die Ergebnisse im Zusammenhang erklären.","ai.family.response.activities":"Die Aktivitätsleistung zeigt, was während der NeuroBridge-Übungen aufgezeichnet wurde. Sie ist weder Diagnose noch Behandlungsempfehlung.","ai.family.response.care":"Ich kann Fragen vorbereiten wie:\n• Was hat sich bei der aufgezeichneten Leistung verändert?\n• Worauf sollten wir uns vor dem nächsten Termin konzentrieren?\n• Welche Aktivitäten sollten wir gemeinsam ansehen?","ai.family.response.settings":"Öffnen Sie Einstellungen in der Seitenleiste, um Sprache, Konto und Barrierefreiheit zu prüfen.","ai.family.response.usage":"Über die Seitenleiste öffnen Sie Erinnerungen, Aktivitäten, Berichte, Termine oder Nachrichten. Sagen Sie mir, was Sie tun möchten.","ai.family.response.unknown":"Ich bin noch nicht sicher, was Sie meinen. Ich helfe bei Aktivitäten, Erinnerungen, Berichten, Terminen, unterstützenden Nachrichten oder Fragen an das Betreuungsteam.",
